custom_css:
/*header*/
.header-wrapper.header-double-menu .container-wrapper {
    border-bottom:none;
}
.page-wrapper{
    border:40px solid #f0f1f3;
    border-radius:75px;
}
.template-content{
    background:#f0f1f3;
}
header.header.header.main-header.header-bg-block{
    width:70%;
    margin:0 auto;
    border-radius:0 0 200px 200px;
}
.single-post.et-header-overlap .main-header {
    background-color: #f0f1f3 !important
}

.fixed-header{
    border:none;
}
body ul.menu li a::after{
    display:none !important;
}

/*Bredcrambs*/
 .page-heading h1 span:after{
    position: relative;
    right: -10px;
    content:url(http://8theme.com/demo/xstore/2/x-phone/wp-content/uploads/sites/5/2017/12/title-before.png);
 }
 .title-before{
     letter-spacing:-1px;
 }
 .title-before:after{
    position: relative;
    right: -5px;
    content:url(http://8theme.com/demo/xstore/2/x-phone/wp-content/uploads/sites/5/2017/12/little-title-img.png);
 }
 
 /*content*/
 
  .vc_gitem-animated-block ,
  .home-gallery .mpc-item.mpc-transition{
    position: relative;
    overflow: hidden;
    cursor: pointer;
    -webkit-transition: all 0.3s ease-in-out;
    transition: all 0.3s ease-in-out;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    border-radius:20px !important;
}
 .vc_gitem-animated-block:hover .vc_gitem-zone,
 .home-gallery .mpc-item.mpc-transition:hover img{
    -webkit-transform: scale(1.08);
    -ms-transform: scale(1.08);
    transform: scale(1.08);
    transition: all 0.4s ease-in-out;
    border-radius:20px !important;
}
 .vc_gitem-animated-block .vc_gitem-zone,
 .home-gallery .mpc-item.mpc-transition img{
    transition: all 0.5s ease-in-out !important;
    border-radius:20px !important;
}
 
 .pulse-play {
    animation-name: pulse;
    -webkit-animation-name: pulse;
    animation-duration: 1.5s;
    -webkit-animation-duration: 1.5s;
    animation-iteration-count: infinite;
    -webkit-animation-iteration-count: infinite;
}
 .initial{
     text-transform:initial !important;
 }
 .shadow .mpc-button.mpc-transition,
 .single_add_to_cart_button,
 .button-iphone-block .mpc-button.mpc-transition:hover,
 .Iphon:hover > .vc_column-inner{
     box-shadow: 10px 8px 25px #c8c8c8;
 }
 .Iphon:hover > .vc_column-inner{
     border-radius:63px;
 }
 
/*blog*/
.home .meta-post *,
.home .post-comments-count span:last-child{
    font-family: "Work Sans";
    text-transform: initial;
    font-weight: 500;
    color:#f02073 !important;
    font-size:15px;
}
.home .post-heading h2{
    font-size:21px !important;
    letter-spacing: -1px;
}
.home .post-heading{
    margin-top:12px;
}
.home .post-heading,
.home .post-heading h2{
    margin-bottom:17px !important;
}

.blog-post .wp-picture {
	border-radius: 20px;
	-webkit-transform: translateZ(0);
}

.post-categories{
    display:none;
}
body .read-more{
    color:#2d2e3c;
    font-size:16px;
    font-family: "Work Sans";
    font-weight:400;
}
.articles-pagination a,
.articles-pagination span{
    border:none;
    border-radius:50%;
    font-family: "Work Sans";
    font-weight: 500;
}
.blog article.content-small .wp-picture,
.blog article.content-chess .wp-picture {
    max-width: 44%;
}
.page-numbers.current,
.articles-pagination a:hover{
    border-radius:50%;
}
.single-post  .post-header .post-heading h2 {
    text-transform: inherit;
    letter-spacing: 0;
    font-size: 28px;
    font-weight: 500;
}
.single-post .post-template-framed .post-header .post-heading{
    border-radius:20px;
}
.single-post .meta-post {
    font-size: 18px;
}

.et_coutn-posts{
    display:none;
}
.articles-pagination {
     border-top:none; 
    border-bottom:none; 
    margin-bottom: 6.28em;
}
.blog .meta-post{
    font-size:18px;
}
.blog .post-heading h2.entry-title{
    font-size: 30px;
    letter-spacing: 0;
}
.blog .post-heading {
    margin-bottom: .5em;
}
.post-comments-count span:last-child{
    color:#a0a0a0 !important;
}
.read-more:before{
    background:#2d2e3c !important;
}
textarea.form-control:focus, 
textarea:focus,
input[type="text"]:focus{
    border-color: #f02073;
}
.single-post .comment-respond *{
    text-align:center;
}
.single-post input[type="text"]{
    height:50px;
    font-size:16px;
    color:#a0a0a0;
}
.comment-reply-title span{
    font-size:30px;
    color:#2d2e3c;
}
.single-post textarea{
    height:120px;
    font-size:16px;
    color:#a0a0a0;
}
.form-group{
    margin-bottom:30px;
}
.single-post .form-submit .submit:hover,
.wpcf7-form-control.wpcf7-submit:hover,
.single_add_to_cart_button:hover,
.vc_general.vc_btn3.vc_btn3-size-md:hover,
.read-more.btn:hover{
    background: linear-gradient(135deg, #fa0d5c 100%,#4676b1 100%,#4676b1 100%);
}
.single_add_to_cart_button{
    margin-bottom:25px !important;
}
.vc_general.vc_btn3.vc_btn3-size-md{
    line-height: 25px;
    margin-top: 40px;
    margin-bottom: 0 !important;
    box-shadow: 10px 8px 25px #c8c8c8;
}
.single-post .form-submit .submit,
.wpcf7-form-control.wpcf7-submit,
.single_add_to_cart_button,
.vc_general.vc_btn3.vc_btn3-size-md,
.read-more.btn{
    border-radius:30px !important;
    font-size:18px;
    text-transform:initial;
    height:56px;
    width:210px;
    background: linear-gradient(135deg, #fa0d5c 23%,#af7395 53%,#4676b1 100%,#4676b1 100%);
    border:none;
    margin-bottom: 100px;
    color:#fff;
     font-family: "Work Sans";
    font-weight: 500;
    
}
.single-post .page-heading.bc-size-large .title {
    max-width: 1000px;
    line-height: 70px;
    font-size: 70px;
}
.single-post article.blog-post {
    margin-bottom: -5px;
}
.comment-reply-title {
    border-bottom:none;
}
.share-post .menu-social-icons li a {
    padding: 10px;
    background: #f5f5f5;
    margin: 0 5px;
    border-radius: 30px;
    width: 36px;
    height: 36px;
}
.single-post .share-title{
    padding-top:5px;
}
.share-post .menu-social-icons li a:hover {
   background: #f02073;
}
.share-post .menu-social-icons li a:hover i{
    color:#fff;
}
.share-post .menu-social-icons li a i {
   font-size:15px;
}
/*Shop*/
.product-information table.variations tr:last-child td.value select{
    margin:20px auto !important;
}
.variations{
    width:100% !important;
}
.product-content .compare:before {
    left: 510px;
}
.single-product-default .product-content .col-md-6.col-sm-12.product-images,
.single-product-default .product-content .col-md-6.col-sm-12.product-information {
    width:100% !important;
    text-align:center !important;
}
.single-product-default .product-content *{
    text-align:center !important;
}
.wc-tabs.tabs-nav,
.sku_wrapper{
    display:none !important;
}
.single-product .product-information-inner h4.title {
    font-size: 36px;
    text-transform:initial;
    margin-top:30px;
}
.single-product .product-information-inner .price{
    font-family: "Work Sans";
    font-weight:500;
    font-size: 36px;
    color: #2d2e3c;
}
.minus:hover:before,
.plus:hover:before{
    color: #f02073 !important;
}
.quantity.buttons_added.buttons_added input[type="number"] {
    margin-left: -1px;
    margin-right: -1px;
}
.minus,
.plus,
.minus + .input-text {
    background: transparent !important;
    border: 1px solid #d1d1d1 !important;
    color: #4d4d4d !important;
}
.qty-span{
    margin-bottom:30px;
}
.short-description p{
    width:80%;
    margin:0 auto;
}
span.tagged_as{
    text-transform:uppercase !important;
}
.qty-span,
span.tagged_as,
.compare.button,
.product-information table.variations td.label label{
    font-size: 18px !important;
    font-family: "Work Sans";
    font-weight: 500 !important;
    display: block;
    text-transform: capitalize;
    color: #2d2e3c;
}
body .product-information-inner span.tagged_as a{
    font-family: Raleway !important;
    font-weight:300 !important;
    color:#a0a0a0;
    text-transform:lowercase !important;
    font-size:14px !important;
}
/*footer*/
footer.footer .et-follow-buttons.buttons-size-normal a {
    padding: 0 6px;
}
footer.footer .et-follow-buttons.buttons-size-normal a:hover i,
footer.footer ul li a:hover{
    color:#f02073 !important;
}
.menu-element.horizontal li {
    padding: 0 30px;
}
body footer.footer ul li a{
    color:#161616 !important;
    text-transform:initial !important;
    font-size:17px !important;
    font-family: "Work Sans";
    font-weight: 400;
}

@media screen and (min-width: 1900px) {
    header.header.header.main-header.header-bg-block{
       width:50%;
    }
}

/*responsive*/
@media screen and (max-width: 780px) {
   .page-wrapper{
     border:none;
   }
   .navbar-toggle span{
        background:#2d2e3c !important;
    }
    .navbar-toggle{
        top:55% !important;
    }
    .single-post .page-wrapper > .container{
        background:#fff !important;
    }
}

@media screen and (max-width: 480px) {
    .single-post .page-heading .title {
       font-size: 40px !important;
       line-height: 40px !important;
     }
    .single-product .page-heading .title {
      font-size: 53px !important;
      line-height: 53px !important;
    }
    .responsive-size{
        font-size:45px !important;
    }
    .parametrs-iphone p{
        border-bottom:none !important;
    }
    body .price-iphone > div > .vc_column-inner{
        margin:0 0 50px 0 !important;
        background-size: contain !important
    }
    .parametrs-iphone .vc_col-sm-7{
        width:70% !important;
        float:left;
    }
    .et-header-overlap .page-heading,
    .et-header-overlap .page-heading.bc-size-small {
       padding-top: 9em !important;
    }
    .page-heading .title{
        font-size: 58px !important;
        line-height: 58px !important;
    }
    .map-section > div > .vc_column-inner {
        padding-right:0 !important;
        padding-left:0 !important;
    }
    body .map-info{
      right: 0px !important;
    }
    .single-post .page-heading.bc-size-large .title {
      line-height: 45px;
      font-size: 45px;
    }
    .blog .meta-post{
        margin:10px 0;
    }
    .read-more{
        margin: 40px auto 10px !important;
    }
    .blog article.blog-post *{
        text-align:center;
    }
    .blog article.content-small .wp-picture, .blog article.content-chess .wp-picture {
       max-width: 100%; 
    }
    .container.content-page{
        background:#fff;
    }
    .responsiv-bottom-30{
        margin-bottom:30px;
    }
    body .video-block {
        min-height: auto !important;
    }
     body .video-block h2{
        font-size: 45px !important;
     }
    body .paralax-block h2{
        font-size: 45px !important;
        text-shadow: 1px 2px 1px #FFE;
    }
    body .video-block,
    body .paralax-block{
        border-right:none !important;
        border-left:none !important;
        padding-left: 0 !important;
        padding-right: 0 !important;
    }
    .mpc-hotspot.mpc-transition{
        display:none;
    }
    .gallery-grid .mpc-image img{
        margin:0 auto;
    }
    .header-wrapper header .container-wrapper {
      padding: 10px 0 6px 0 !important;
    }
   .footer {
      padding-top: 50px !important;
      padding-bottom: 50px !important;
    }
   .page-wrapper{
     border:none;
   }
   footer.footer *{
     text-align:center !important;
   }
   .menu-element.horizontal li {
     padding: 0 19px !important;
   }
   footer.footer .et-follow-buttons.buttons-size-normal,
   footer.footer .vc_col-lg-offset-1{
     margin-bottom:20px;
   }
   header.header.header.main-header.header-bg-block {
     width: 100%; 
     margin: 0 auto; 
     border-radius: inherit !important; 
   }
   .content > div:first-child,
   .content > div:first-child > div > .vc_column-inner {
       padding-left:0 !important;
       padding-right:0 !important;
   }
   
}
